# M-050: AsyncAPI 3 contract of the events Sangam sends and receives (sangam-events.asyncapi.yaml), generated by
# gen_openapi.py. Every name below comes from the code; the source is cited next to it. EventContractTest
# (sangam-server) checks the envelopes, headers and type lists against the classes; AsyncApiConsistencyTest
# (sangam-rest) checks the documents against each other and the audit catalogue against SANGAM.md X.4.0.3.
#
# Scope: the external surfaces of the outbox relay (core Publisher implementations registered in PublisherRegistry):
#   webhook:<name>  HttpWebhookPublisher, CloudEvents binary mode (any outbox event routed there)
#   channel:<key>   ChannelPublisher, event-registry outbound events over http, kafka, jms or rabbitmq
#   rollup:national RollupPublisher, CloudEvents structured mode (cell to roll-up)
#   xcell:<tenant>  CrossCellPublisher, cross-cell business message through the gateway
# and the inbound broker inbox (InboundMapper). In-process destinations (history-projector, pack-dispatch, *-notify,
# ledger:gl, sangam.registry.publish, sangam.resources.*) are not wire contracts and are not listed.

ANY = {}


def props(spec, descs=None, typed=None):
    """Object properties from a space-separated name list; `typed` gives the JSON schema of the names whose Java type
    was checked, every other name is untyped (any JSON)."""
    out = {}
    for n in spec.split():
        p = dict((typed or {}).get(n, ANY))
        if descs and n in descs:
            p["description"] = descs[n]
        out[n] = p
    return out


def obj(desc, spec, descs=None, typed=None, required=(), open_=True):
    s = {"type": "object", "description": desc, "properties": props(spec, descs, typed)}
    if required:
        s["required"] = list(required)
    if open_:
        s["additionalProperties"] = True
    return s


